    {!event ? <>
      <div className="tournament-form"><label htmlFor="players">Players</label><select className="control" id="players" value={count} onChange={(e) => setCount(Number(e.currentTarget.value))}><option value={4}>4</option><option value={8}>8</option></select>
        {names.slice(0, count).map((name, i) => <div className="name-field" key={i}><label htmlFor={`player-${i}`}>Player {i + 1}</label><input className="control" id={`player-${i}`} value={name} onChange={(e) => { const next = [...names]; next[i] = e.currentTarget.value; setNames(next); }} /></div>)}
        <button className="control" type="button" onClick={start}>Start tournament</button>
      </div>
      <h3>Past tournaments</h3>{blocked && <p>Progress won't be saved on this device.</p>}
      {history.length === 0 ? <p>No past tournaments yet.</p> : <ul>{history.map((t, i) => <li key={i}><button className="control" type="button" onClick={() => { setEvent(t); setPlaying(false); }}>Champion: {t.names[t.matches[t.index]!.winner!]}</button></li>)}</ul>}
