      {!complete && match!.winner !== null && <button className="control" type="button" onClick={() => { setEvent({ ...event, index: event.index + 1 }); setPlaying(false); }}>Next match</button>}
      <div className="bracket"><table><caption>Bracket</caption><thead><tr><th scope="col">Round</th><th scope="col">Player</th><th scope="col">Moves</th><th scope="col">Time</th><th scope="col">Player</th><th scope="col">Moves</th><th scope="col">Time</th><th scope="col">Winner</th></tr></thead><tbody>{event.matches.map((m, i) => <tr key={i}><td>{i < event.names.length / 2 ? (event.names.length === 8 ? 'Quarterfinal' : 'Semifinal') : i < event.matches.length - 1 ? 'Semifinal' : 'Final'}</td>{m.players.map((player, j) => <><td key={`p${j}`}>{player === null ? 'TBD' : event.names[player]}</td><td key={`m${j}`}>{m.results[j]?.moves ?? '—'}</td><td key={`t${j}`}>{m.results[j] ? formatElapsed(m.results[j]!.elapsedMs) : '—'}</td></>)}<td>{m.winner === null ? '—' : event.names[m.winner]}</td></tr>)}</tbody></table></div>
      {complete ? <button className="control" type="button" onClick={back}>Back to game</button> : <button className="control" type="button" onClick={() => requestLeave(() => { setEvent(null); setPlaying(false); })}>Leave tournament</button>}
    </>}
    <div className="exchange"><label htmlFor="tournament-json">Tournament JSON</label><textarea id="tournament-json" className="control" rows={7} value={draft} onChange={(e) => setDraft(e.currentTarget.value)} /><div className="exchange-buttons"><button className="control" type="button" onClick={() => { setDraft(exportTournament(event)); setNotice('Tournament exported.'); }}>Export tournament</button><button className="control" type="button" onClick={load}>Load tournament</button></div><p role="status" aria-live="polite">{notice}</p></div>
    <dialog ref={dialog} onCancel={(e) => { e.preventDefault(); dialog.current?.close(); setConfirmAction(null); }}><p>Leave unfinished work?</p><div className="exchange-buttons"><button className="control" ref={keep} type="button" onClick={() => { dialog.current?.close(); setConfirmAction(null); }}>Keep playing</button><button className="control" type="button" onClick={() => { dialog.current?.close(); confirmAction?.(); setConfirmAction(null); }}>Leave</button></div></dialog>
  </main>;
}
