import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX, isWon } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from '../session/fresh-board.ts';

export interface Result {
  moves: number;
  elapsedMs: number;
}
export interface Match {
  boardCode: string;
  players: [number | null, number | null];
  results: [Result | null, Result | null];
  winner: number | null;
}
export interface Tournament {
  names: string[];
  matches: Match[];
  index: number;
}

export function normalizeName(name: string): string {
  return name.trim().replace(/\s+/gu, ' ').normalize('NFC');
}
export function nameError(names: string[]): string {
  if (names.some((name) => [...name].length < 2 || [...name].length > 20))
    return 'Use 2 to 20 characters.';
  if (new Set(names.map((name) => name.toLowerCase())).size !== names.length)
    return 'Each name must be different.';
  return '';
}
export function makeTournament(names: string[]): Tournament {
  const pairs =
    names.length === 4
      ? [
          [0, 3],
          [1, 2],
        ]
      : [
          [0, 7],
          [3, 4],
          [2, 5],
          [1, 6],
        ];
  const codes = new Set<string>();
  const matches: Match[] = [];
  for (let i = 0; i < names.length - 1; i++) {
    const size = i < names.length / 2 ? (names.length === 8 ? 4 : 6) : i < names.length - 2 ? 6 : 8;
    let code: string;
    do {
      code = freshBoardCode(size);
    } while (codes.has(code));
    codes.add(code);
    const pair = pairs[i];
    matches.push({
      boardCode: code,
      players: pair ? [pair[0]!, pair[1]!] : [null, null],
      results: [null, null],
      winner: null,
    });
  }
  return { names, matches, index: 0 };
}
export function recordResult(t: Tournament, result: Result): Tournament {
  const matches = t.matches.map((m) => ({
    ...m,
    players: [...m.players] as Match['players'],
    results: [...m.results] as Match['results'],
  }));
  const match = matches[t.index]!;
  const turn = match.results[0] === null ? 0 : 1;
  match.results[turn] = result;
  if (match.results[0] && match.results[1]) {
    const a = match.results[0],
      b = match.results[1];
    match.winner =
      a.moves !== b.moves
        ? match.players[a.moves < b.moves ? 0 : 1]
        : a.elapsedMs !== b.elapsedMs
