    {
      format: 'neon-pairs/tournament',
      snapshot: snapshot ? (JSON.parse(snapshot) as unknown) : null,
      tournament: t,
      version: 1,
    },
    sort,
    2,
  );
}
export function importTournament(text: string): {
  tournament: Tournament | null;
  snapshot: string | null;
  error: string;
} {
  try {
    if (new TextEncoder().encode(text).length > 65536) throw 0;
    const value: unknown = JSON.parse(text);
    if (!object(value)) throw 0;
    for (const key of Object.keys(value))
      if (!['format', 'snapshot', 'tournament', 'version'].includes(key))
        return { tournament: null, snapshot: null, error: `Unknown field: ${key}.` };
    if (
      !keys(value, ['format', 'snapshot', 'tournament', 'version']) ||
      value.format !== 'neon-pairs/tournament' ||
      value.version !== 1 ||
      (value.tournament !== null && !validateTournament(value.tournament))
    )
      throw 0;
    const snapshot = value.snapshot === null ? null : JSON.stringify(value.snapshot);
    if (snapshot) {
      const game = decodeSnapshot(snapshot);
      const t = value.tournament as Tournament | null;
      if (
        !game ||
        isWon(game) ||
        !t ||
        t.matches[t.index]!.winner !== null ||
        game.boardCode !== t.matches[t.index]!.boardCode
      )
        throw 0;
    }
    return { tournament: value.tournament as Tournament | null, snapshot, error: '' };
  } catch {
    return { tournament: null, snapshot: null, error: 'Invalid tournament.' };
  }
}
import { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { RefObject } from 'react';
import type { BoardFocus } from '../board/Board.tsx';
import { formatElapsed } from '../elapsed-time.ts';
import { isWon } from '../game.ts';
import { useGame } from '../session/use-game.ts';
import { GameStatus } from '../status/GameStatus.tsx';
import {
  exportTournament,
  importTournament,
  makeTournament,
  nameError,
  normalizeName,
  recordResult,
  validateTournament,
} from './model.ts';
import type { Result, Tournament } from './model.ts';
import './tournament.css';

const KEY = 'np3:tournaments';
function readHistory(): { items: Tournament[]; blocked: boolean } {
  try {
    const text = localStorage.getItem(KEY);
    if (!text) return { items: [], blocked: false };
    const value: unknown = JSON.parse(text);
    if (typeof value !== 'object' || value === null || Array.isArray(value))
      return { items: [], blocked: false };
    const data = value as Record<string, unknown>;
    if (
      Object.keys(data).length !== 2 ||
      data.v !== 3 ||
      !Array.isArray(data.items) ||
      data.items.length > 10 ||
      !data.items.every(
        (item: unknown) =>
          validateTournament(item) &&
          item.index === item.matches.length - 1 &&
          item.matches[item.index]!.winner !== null,
      )
    )
      return { items: [], blocked: false };
    return { items: data.items as Tournament[], blocked: false };
  } catch (error) {
    return { items: [], blocked: !(error instanceof SyntaxError) };
  }
}
function Turn({
  code,
  finished,
  snapshot,
  exporter,
  announce,
}: {
  code: string;
  finished(result: Result): void;
  snapshot: string | null;
  exporter: RefObject<(() => string) | null>;
  announce(message: string): void;
}) {
  const { session, activate, loadSnapshot, resume, exportSnapshot } = useGame(code);
  exporter.current = exportSnapshot;
  useEffect(() => {
    if (snapshot) loadSnapshot(snapshot);
  }, []);
  const board = useRef<BoardFocus>(null);
  const reported = useRef(false);
  useEffect(() => {
    if (session.feedback) announce(session.feedback);
  }, [session.announcement]);
  useEffect(() => {
    if (isWon(session.game) && !reported.current) {
      reported.current = true;
      finished({ moves: session.game.moves, elapsedMs: session.game.elapsedMs });
    }
  }, [session.game, finished]);
  return (
    <>
      {session.paused && (
        <button className="control" type="button" onClick={resume}>
          Resume
        </button>
      )}
      <GameStatus game={session.game} best={undefined} celebration={session.celebration} />
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      <Board game={session.game} activate={activate} ref={board} />
    </>
  );
}
export function TournamentScreen({ back }: { back(): void }) {
  const [historyState] = useState(readHistory);
  const [history, setHistory] = useState(historyState.items);
  const [blocked, setBlocked] = useState(historyState.blocked);
  const [count, setCount] = useState(4);
  const [names, setNames] = useState(Array<string>(8).fill(''));
  const [event, setEvent] = useState<Tournament | null>(null);
  const [playing, setPlaying] = useState(false);
  const [playingTurn, setPlayingTurn] = useState(0);
  const [snapshot, setSnapshot] = useState<string | null>(null);
  const exporter = useRef<(() => string) | null>(null);
  const [draft, setDraft] = useState('');
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState({ text: '', id: 0 });
  function announce(text: string) {
    setAnnouncement((old) => ({ text, id: old.id + 1 }));
  }
  useEffect(() => {
    if (notice) announce(notice);
  }, [notice]);
  const [confirmAction, setConfirmAction] = useState<(() => void) | null>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  useLayoutEffect(() => {
    heading.current?.focus();
  }, []);
  useEffect(() => {
    if (confirmAction) {
      dialog.current?.showModal();
      keep.current?.focus();
    }
  }, [confirmAction]);
  const match = event?.matches[event.index];
  const complete = !!event && event.index === event.matches.length - 1 && match?.winner !== null;
  function requestLeave(action: () => void) {
    if (event && !complete) setConfirmAction(() => action);
    else action();
  }
  function save(t: Tournament) {
    const next = [t, ...history].slice(0, 10);
    setHistory(next);
    try {
      localStorage.setItem(KEY, JSON.stringify({ v: 3, items: next }));
    } catch {
      setBlocked(true);
    }
  }
  function start() {
    const accepted = names.slice(0, count).map(normalizeName);
    const error = nameError(accepted);
    if (error) {
      setNotice(error);
      return;
    }
    setNotice('');
    setEvent(makeTournament(accepted));
    setPlaying(false);
  }
  function finish(result: Result) {
    if (!event) return;
    const next = recordResult(event, result);
    setEvent(next);
    if (next.index === next.matches.length - 1 && next.matches[next.index]!.winner !== null)
      save(next);
  }
  function load() {
    const result = importTournament(draft);
    if (result.error) {
      setNotice(result.error);
      return;
    }
    const loaded = result.tournament;
    requestLeave(() => {
      setEvent(loaded);
      setSnapshot(result.snapshot);
      setPlaying(!!result.snapshot);
      setPlayingTurn(loaded?.matches[loaded.index]?.results[0] === null ? 0 : 1);
      setNotice('Tournament loaded.');
    });
  }
  const turn = match?.results[0] === null ? 0 : 1;
  useEffect(() => {
    if (event && match && !complete)
      announce(`Now playing: ${event.names[match.players[match.results[0] === null ? 0 : 1]!]}`);
  }, [event?.index, match?.results[0], complete]);
  const round =
    event &&
    (event.index < event.names.length / 2
      ? event.names.length === 8
        ? 'Quarterfinal'
        : 'Semifinal'
      : event.index < event.matches.length - 1
        ? 'Semifinal'
        : 'Final');
  return (
    <main className="tournament">
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!event ? (
        <>
          <div className="tournament-form">
            <label htmlFor="players">Players</label>
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            {names.slice(0, count).map((name, i) => (
              <div className="name-field" key={i}>
                <label htmlFor={`player-${i}`}>Player {i + 1}</label>
                <input
                  className="control"
                  id={`player-${i}`}
                  value={name}
                  onChange={(e) => {
                    const next = [...names];
                    next[i] = e.currentTarget.value;
                    setNames(next);
                  }}
                />
              </div>
            ))}
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
          </div>
          <h3>Past tournaments</h3>
          {blocked && <p>Progress won't be saved on this device.</p>}
          {history.length === 0 ? (
            <p>No past tournaments yet.</p>
          ) : (
            <ul>
              {history.map((t, i) => (
                <li key={i}>
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setEvent(t);
                      setPlaying(false);
                    }}
                  >
                    Champion: {t.names[t.matches[t.index]!.winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
          <button className="control" type="button" onClick={back}>
            Back to game
          </button>
        </>
      ) : (
        <>
          {complete ? (
            <p className="champion">Champion: {event.names[match!.winner!]}</p>
          ) : (
            <>
              <p>Round: {round}</p>
              <p>Now playing: {event.names[match!.players[turn]!]}</p>
            </>
          )}
          {!complete && !playing && match!.winner === null && (
            <button
              className="control"
              type="button"
              onClick={() => {
                setSnapshot(null);
                setPlayingTurn(turn);
                setPlaying(true);
              }}
            >
              Start turn
            </button>
          )}
          {!complete && playing && (
            <Turn
              key={`${event.index}-${playingTurn}`}
              code={match!.boardCode}
              finished={finish}
              snapshot={snapshot}
              exporter={exporter}
              announce={announce}
            />
          )}
          {!complete && playing && playingTurn === 0 && match!.results[0] && !match!.results[1] && (
            <button className="control" type="button" onClick={() => setPlaying(false)}>
              Next turn
            </button>
          )}
          {!complete && match!.winner !== null && (
            <button
              className="control"
              type="button"
              onClick={() => {
                setEvent({ ...event, index: event.index + 1 });
                setPlaying(false);
              }}
            >
              Next match
            </button>
          )}
          <div className="bracket">
            <table>
              <caption>Bracket</caption>
              <thead>
                <tr>
                  <th scope="col">Round</th>
                  <th scope="col">Player</th>
                  <th scope="col">Moves</th>
                  <th scope="col">Time</th>
                  <th scope="col">Player</th>
                  <th scope="col">Moves</th>
                  <th scope="col">Time</th>
                  <th scope="col">Winner</th>
                </tr>
              </thead>
              <tbody>
                {event.matches.map((m, i) => (
                  <tr key={i}>
                    <td>
                      {i < event.names.length / 2
                        ? event.names.length === 8
                          ? 'Quarterfinal'
                          : 'Semifinal'
                        : i < event.matches.length - 1
                          ? 'Semifinal'
                          : 'Final'}
                    </td>
                    {m.players.map((player, j) => (
                      <Fragment key={j}>
                        <td>{player === null ? 'TBD' : event.names[player]}</td>
                        <td>{m.results[j]?.moves ?? '—'}</td>
                        <td>{m.results[j] ? formatElapsed(m.results[j]!.elapsedMs) : '—'}</td>
                      </Fragment>
                    ))}
                    <td>{m.winner === null ? '—' : event.names[m.winner]}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {complete ? (
            <button className="control" type="button" onClick={back}>
              Back to game
            </button>
          ) : (
            <button
              className="control"
              type="button"
              onClick={() =>
                requestLeave(() => {
                  setEvent(null);
                  setPlaying(false);
                })
              }
            >
              Leave tournament
            </button>
          )}
        </>
      )}
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={announcement.id}>{announcement.text}</span>
        </p>
      </div>
      <div className="exchange">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={7}
          value={draft}
          onChange={(e) => setDraft(e.currentTarget.value)}
        />
        <div className="exchange-buttons">
          <button
            className="control"
            type="button"
            onClick={() => {
              setDraft(
                exportTournament(
                  event,
                  playing && match?.results[playingTurn] === null
                    ? (exporter.current?.() ?? null)
                    : null,
                ),
              );
              setNotice('Tournament exported.');
            }}
          >
            Export tournament
          </button>
          <button className="control" type="button" onClick={load}>
            Load tournament
          </button>
        </div>
        <p>{notice}</p>
      </div>
      <dialog
        ref={dialog}
        onCancel={(e) => {
          e.preventDefault();
          dialog.current?.close();
          setConfirmAction(null);
        }}
      >
        <p>Leave unfinished work?</p>
        <div className="exchange-buttons">
          <button
            className="control"
            ref={keep}
            type="button"
            onClick={() => {
              dialog.current?.close();
              setConfirmAction(null);
            }}
          >
            Keep playing
          </button>
          <button
            className="control"
            type="button"
            onClick={() => {
              dialog.current?.close();
              confirmAction?.();
              setConfirmAction(null);
            }}
          >
            Leave
          </button>
        </div>
      </dialog>
    </main>
  );
}

